WITH cleaned AS (SELECT *, CAST(rating AS INT) AS rating_int, COALESCE(city, 'OTHER') AS city_clean FROM suppliers WHERE LENGTH(supplier_name) > 7), eligible AS (SELECT s.* FROM cleaned s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.cost < 280)), deduped AS (SELECT *, RANK() OVER (PARTITION BY city, country ORDER BY rating_int NULLS FIRST) AS row_num FROM eligible QUALIFY row_num = 1) SELECT *, SUM(rating) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating DESC, id) AS seq_no, SUM(rating_int) OVER w_part AS cumulative_rating_int, LAG(rating, 2) OVER (PARTITION BY city, country ORDER BY rating_int, id) AS prev_rating, MAX(rating_int) OVER (PARTITION BY city) AS city_max_rating_int FROM deduped WINDOW w_part AS (PARTITION BY city ORDER BY rating_int, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
